const crypto = require('crypto');
const input = $input.first().json;
const headers = input.headers || {};
const body = input.body || {};
const header = (name) => headers[name.toLowerCase()] || headers[name] || '';
const timestamp = String(header('X-Aptohire-Timestamp'));
const supplied = String(header('X-Aptohire-Signature')).replace(/^sha256=/i, '').toLowerCase();
if (typeof $env.N8N_WEBHOOK_SECRET !== 'string' || $env.N8N_WEBHOOK_SECRET.length < 32) throw new Error('webhook secret is not configured');
if (!/^\d{10}$/.test(timestamp) || Math.abs(Math.floor(Date.now()/1000)-Number(timestamp)) > 300) throw new Error('stale or invalid timestamp');
if (body.kind !== 'assign' || typeof body.run_id !== 'string' || !body.run_id || body.prompt_version !== 'assign@1' || !body.payload || typeof body.payload !== 'object' || Array.isArray(body.payload) || Object.keys(body).sort().join(',') !== 'kind,payload,prompt_version,run_id') throw new Error('invalid job contract');
if (Buffer.byteLength(JSON.stringify(body), 'utf8') > 128000) throw new Error('job payload too large');
const provider = new URL($env.N8N_LLM_CHAT_COMPLETIONS_URL);
const providerHost = provider.hostname.toLowerCase().replace(/\.$/, '');
const allowedHosts = String($env.N8N_LLM_ALLOWED_HOSTS || '').split(',').map((host) => host.trim().toLowerCase().replace(/\.$/, '')).filter(Boolean);
if (provider.protocol !== 'https:' || provider.username || provider.password || provider.search || provider.hash || (provider.port && provider.port !== '443') || !provider.pathname.endsWith('/chat/completions') || !allowedHosts.includes(providerHost) || !providerHost.includes('.') || providerHost.includes(':') || /^\d{1,3}(?:\.\d{1,3}){3}$/.test(providerHost) || providerHost === 'localhost' || providerHost.endsWith('.localhost') || providerHost.endsWith('.local') || providerHost.endsWith('.internal') || providerHost.endsWith('.test') || providerHost.endsWith('.invalid')) throw new Error('invalid provider endpoint configuration');
const raw = JSON.stringify(body);
const expected = crypto.createHmac('sha256', $env.N8N_WEBHOOK_SECRET).update(`${timestamp}.${raw}`).digest('hex');
const a = Buffer.from(expected, 'hex'); const b = Buffer.from(supplied, 'hex');
if (a.length !== b.length || !crypto.timingSafeEqual(a,b)) throw new Error('invalid HMAC');
return [{json:{run_id:body.run_id,kind:body.kind,prompt_version:body.prompt_version,payload:body.payload}}];

const crypto = require('crypto');
const base = $('Verify Request').first().json;
const content = $input.first().json?.choices?.[0]?.message?.content;
if (typeof content !== 'string') throw new Error('model returned no JSON content');
const result = JSON.parse(content);
const keys = Object.keys(result).sort().join(',');
if (keys !== 'originality_questions,scenario,title,video_guidance' || typeof result.title !== 'string' || !result.title.trim() || result.title.length > 120 || typeof result.scenario !== 'string' || !result.scenario.trim() || result.scenario.length > 700 || typeof result.video_guidance !== 'string' || !result.video_guidance.trim() || result.video_guidance.length > 700 || !Array.isArray(result.originality_questions) || result.originality_questions.length < 2 || result.originality_questions.length > 3 || result.originality_questions.some((x) => typeof x !== 'string' || !x.trim() || x.length > 300)) throw new Error('invalid assignment result');
if (typeof $env.CALLBACK_SECRET !== 'string' || $env.CALLBACK_SECRET.length < 32) throw new Error('response signature secret is not configured');
const responseBody = JSON.stringify({run_id:base.run_id,kind:base.kind,result});
if (Buffer.byteLength(responseBody, 'utf8') > 64000) throw new Error('agent result too large');
const timestamp = String(Math.floor(Date.now()/1000));
const signature = crypto.createHmac('sha256', $env.CALLBACK_SECRET).update(`${timestamp}.${responseBody}`).digest('hex');
return [{json:{response_body:responseBody,timestamp,signature}}];
